class Solution {
    public: int stoneGameV(vector<int>& stoneValue){
        int n=stoneValue.size();
        vector<int> prefix(n+1);
        for(int i=0;i<n;++i)prefix[i+1]=prefix[i]+stoneValue[i];
        vector<vector<int>> dp(n,vector<int>(n));
        for(int length=2;length<=n;++length)for(int left=0;left+length<=n;++left){
            int right=left+length-1;
            for(int split=left;split<right;++split){
                int leftSum=prefix[split+1]-prefix[left],rightSum=prefix[right+1]-prefix[split+1],candidate;
                if(leftSum<rightSum)candidate=leftSum+dp[left][split];
                else if(leftSum>rightSum)candidate=rightSum+dp[split+1][right];
                else candidate=leftSum+max(dp[left][split],dp[split+1][right]);
                dp[left][right]=max(dp[left][right],candidate);
            }
        }
        return dp[0][n-1];
    }
};
